void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(0.2, 0.81, 0.98, 1); //sky color
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 cloudP = p;
    vec2 grassP = p;
    grassP.x *= 0.7; //shrinking uv in x axis by 30%;
    grassP.y +=1.15;

    cloudP *=1.5;
    grassP *=1.5;
    grassP.x += fract(iTime * .5);
    grassP.x = fract(grassP).x -.5;

    bool reversed = mod(cloudP.y, 2.) <= 1.;
    if(reversed) {
        cloudP.x += easeOutExpo(fract(iTime * 2.));
    }
    else {
        cloudP.x -= easeOutExpo(fract(iTime * 2.));
    }
    cloudP = fract(cloudP) -.5;

    float blur = 1.5 / iResolution.y;





    //cloud

    fragColor = mix(fragColor, vec4(1, 1, 1, 1), smoothstep(blur, -blur, sdCircle(cloudP + vec2(.05, 0.), .1)));
    fragColor = mix(fragColor, vec4(1, 1, 1, 1), smoothstep(blur, -blur, sdCircle(cloudP + vec2(.05, .1), .1)));
    fragColor = mix(fragColor, vec4(1, 1, 1, 1), smoothstep(blur, -blur, sdCircle(cloudP + vec2(.15, .05), .1)));

    fragColor = mix(fragColor, vec4(1, 1, 1, 1), smoothstep(blur, -blur, sdCircle(cloudP + vec2(-0.05, 0.), .1)));
    fragColor = mix(fragColor, vec4(1, 1, 1, 1), smoothstep(blur, -blur, sdCircle(cloudP + vec2(-0.05, .1), .1)));
    fragColor = mix(fragColor, vec4(1, 1, 1, 1), smoothstep(blur, -blur, sdCircle(cloudP + vec2(-0.15, .05), .1)));


    //grass
    fragColor = mix(fragColor, vec4(0.07, 0.84, 0.15, 1), smoothstep(blur, -blur, sdCircle(grassP, .8)));

     //red boxes

    fragColor = mix(fragColor, vec4(0.97, 0.01, 0.2, 1), smoothstep(blur, -blur, sdBox(p, vec2(.32, 1.))));
    fragColor = mix(fragColor, vec4(0.97, 0.01, 0.2, 1), smoothstep(blur, -blur, sdBox(p + vec2((iResolution.x / iResolution.y) - .25, 0), vec2(.25, 1.))));
    fragColor = mix(fragColor, vec4(0.97, 0.01, 0.2, 1), smoothstep(blur, -blur, sdBox(p - vec2((iResolution.x / iResolution.y) - .25, 0), vec2(.25, 1.))));

    //star
    float d = sdStar(rotate(p, iTime), .25, 13, 6.);
    d = smoothstep(-blur, blur, -d);



    fragColor = mix(fragColor, vec4(1, 0.89, 0, 1), d);


}

float sdStar( in vec2 p, in float r, in int n, in float m)
{
    // next 4 lines can be precomputed for a given shape
    float an = 3.141593/float(n);
    float en = 3.141593/m;  // m is between 2 and n
    vec2  acs = vec2(cos(an),sin(an));
    vec2  ecs = vec2(cos(en),sin(en)); // ecs=vec2(0,1) for regular polygon

    float bn = mod(atan(p.x,p.y),2.0*an) - an;
    p = length(p)*vec2(cos(bn),abs(sin(bn)));
    p -= r*acs;
    p += ecs*clamp( -dot(p,ecs), 0.0, r*acs.y/ecs.y);
    return length(p)*sign(p.x);
}

float sdCircle( vec2 p, float r )
{
    return length(p) - r;
}

float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}



vec2 rotate (vec2 p, float angle) {
    float cosA = cos(angle);
    float sinA = sin(angle);

    return vec2(
        p.x * cosA + p.y * sinA,
        p.x * sinA - p.y * cosA
    );
}

float easeOutExpo(float x) {
return x == 1. ? 1. : 1. - pow(2., -10. * x);
}
